def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = day_context['supply']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)

    if budget <= 0:
        return 0

    if not alive_opponents:
        if hp <= 2 or no_water_days >= 1:
            return min(budget, 20)
        return min(budget, 8)

    prev_bids = []
    urgent_opponents = 0
    rich_opponents = 0
    for opp in alive_opponents:
        if opp.get('budget', 0) >= budget:
            rich_opponents += 1
        if opp.get('hp', 10) <= 2 or opp.get('no_water_days', 0) >= 1:
            urgent_opponents += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev.get('bid', 0))

    player_count = 1 + len(alive_opponents)
    expected_units = float(supply) / float(WATER_REQ)
    scarcity = expected_units < player_count

    base = DAILY_SALARY * 0.42
    if supply >= 23:
        base = DAILY_SALARY * 0.28
    elif supply <= 17:
        base = DAILY_SALARY * 0.62

    if scarcity:
        base += 8

    if hp <= 2:
        base = max(base, DAILY_SALARY * 0.9)
    elif hp <= 4 or no_water_days >= 1:
        base = max(base, DAILY_SALARY * 0.72)
    elif hp >= 8 and no_water_days == 0 and supply >= 22:
        base = min(base, DAILY_SALARY * 0.22)

    if prev_bids:
        highest_prev = max(prev_bids)
        avg_prev = sum(prev_bids) / float(len(prev_bids))
        target = max(avg_prev + 1.0, highest_prev + 1.5)
        if highest_prev >= DAILY_SALARY * 0.9:
            if hp > 4 and no_water_days == 0:
                base = min(base, DAILY_SALARY * 0.3)
            else:
                base = max(base, DAILY_SALARY * 0.92)
        else:
            base = max(base, target)

    if urgent_opponents >= max(1, len(alive_opponents) // 2):
        base += 4
    if rich_opponents == len(alive_opponents) and len(alive_opponents) > 0:
        base += 3

    reserve = 0
    if day_context['day'] <= 3:
        reserve = 20
    elif day_context['day'] <= 7:
        reserve = 10

    affordable = max(0, budget - reserve)
    bid = min(base, budget)
    if affordable > 0:
        bid = min(bid, max(affordable, min(budget, 12)))

    if hp <= 2 or no_water_days >= 2:
        bid = min(budget, max(bid, DAILY_SALARY * 0.95))

    if bid < 0:
        bid = 0
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90

    supply = day_context.get('supply', 0.0)
    day = day_context.get('day', 0)

    alive_opponents = []
    for opp_id, opp in opponents_status.items():
        if opp.get('alive', False):
            alive_opponents.append((opp_id, opp))

    # If no opponents, bid conservatively to cover our requirement.
    if not alive_opponents:
        return min(my_status.get('budget', 0), DAILY_SALARY * 0.4)

    # Read yesterday's immediate behavior from previous_trace.
    prev_bids = []
    for _, opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    prev_bids.append(float(b))
                except Exception:
                    pass

    hp = my_status.get('hp', 0)
    budget = my_status.get('budget', 0)

    # Estimate scarcity from supply.
    # Note: use int() for any list indexing; none used here.
    scarcity_factor = 0.0
    if supply <= float(WATER_REQ):
        scarcity_factor = 1.0
    elif supply <= float(WATER_REQ + 3):
        scarcity_factor = 0.7
    elif supply <= 20.0:
        scarcity_factor = 0.4
    else:
        scarcity_factor = 0.2

    # Determine competitive pressure from opponents' previous bids.
    if prev_bids:
        highest_prev_bid = max(prev_bids)
        second_prev_bid = sorted(prev_bids)[-2] if len(prev_bids) >= 2 else highest_prev_bid

        # If someone previously bid very high, we assume they are trying to secure water.
        if highest_prev_bid >= DAILY_SALARY * 0.85:
            # Bid enough to beat the likely winner but preserve budget.
            base = max(highest_prev_bid * 0.98, second_prev_bid + 1.0)
            # If our HP is low, we must prioritize water.
            if hp <= 2:
                target = base
            elif hp <= 3:
                target = base * (1.0 + 0.05 * scarcity_factor)
            else:
                target = base * (0.95 + 0.05 * (1.0 - scarcity_factor))
        else:
            # Low competition signal: bid moderately, slightly above previous leader to ensure advantage.
            leader = highest_prev_bid
            target = max(DAILY_SALARY * (0.45 + 0.2 * scarcity_factor), leader + 2.0)
    else:
        # No signal: bid based on our HP and scarcity.
        if hp <= 2:
            target = DAILY_SALARY * (0.85 + 0.1 * scarcity_factor)
        elif hp <= 3:
            target = DAILY_SALARY * (0.65 + 0.15 * scarcity_factor)
        else:
            target = DAILY_SALARY * (0.5 + 0.1 * scarcity_factor)

    # Keep within budget and avoid extreme overbids.
    # Cap at about 1.1 * daily salary to reduce waste.
    cap = DAILY_SALARY * 1.1
    bid = min(budget, cap, target)

    # Ensure non-negative bid.
    if bid < 0:
        bid = 0

    # Game safety: at least a small amount if budget allows.
    if bid == 0 and budget > 0:
        bid = min(budget, DAILY_SALARY * 0.2)

    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 8
    DAILY_SALARY = 140
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.3)
    # Collect yesterday's bids from alive opponents
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            prev_bids.append(prev['bid'])
    # Determine baseline bid
    if my_status['hp'] <= 2 and my_status['no_water_days'] >= 1:
        # desperate: bid high to ensure water
        base = min(my_status['budget'], DAILY_SALARY * 0.95)
    elif my_status['hp'] <= 4:
        # moderate need
        base = min(my_status['budget'], DAILY_SALARY * 0.7)
    else:
        # comfortable: low bid to save money
        base = min(my_status['budget'], DAILY_SALARY * 0.4)
    # Adjust based on opponent yesterday maximum
    if prev_bids:
        max_prev = max(prev_bids)
        # If opponent bid high yesterday, they may do similar today
        # Slightly outbid if we need water, else undercut
        if max_prev >= DAILY_SALARY * 0.85 and (my_status['hp'] <= 4 or my_status['no_water_days'] > 1):
            # opponent aggressive, we need water: bid just over their high
            bid = min(my_status['budget'], max_prev + 0.5)
        elif max_prev >= DAILY_SALARY * 0.7:
            # moderate pressure
            bid = min(my_status['budget'], max(base, max_prev * 0.9))
        else:
            # opponent low: we can go lower
            bid = min(my_status['budget'], max(base, DAILY_SALARY * 0.35))
    else:
        # no trace, play safe
        bid = base
    # Never bid more than budget, enforce positivity
    bid = max(0, min(my_status['budget'], bid))
    return bid
